content.content:
1	package gitrepo
2	
3	import (
4		"errors"
5		"fmt"
6		"io/fs"
7		"os"
8		"path/filepath"
9		"strings"
10	)
11	
12	// ErrWorktreeMetadataNotFound reports that an explicit worktree root has no
13	// .git entry. Repository opening uses it to distinguish a possible bare
14	// repository from broken worktree metadata.
15	var ErrWorktreeMetadataNotFound = errors.New("worktree Git metadata not found")
16	
17	// WorktreeMetadata contains Git directory facts for one explicit worktree
18	// root. Paths are cleaned and absolute but retain their lexical spelling.
19	type WorktreeMetadata struct {
20		GitDir     string
21		CommonDir  string
22		WorktreeID string
23	}
24	
25	// ResolveWorktreeMetadata resolves filesystem metadata for an explicit
26	// worktree root. It does not discover a root, inspect Git environment
27	// variables, run Git, cache results, or decide caller policy.
28	func ResolveWorktreeMetadata(worktreeRoot string) (WorktreeMetadata, error) {
29		if worktreeRoot == "" {
30			return WorktreeMetadata{}, errors.New("worktree root is required")
31		}
32	
33		root, err := filepath.Abs(worktreeRoot)
34		if err != nil {
35			return WorktreeMetadata{}, fmt.Errorf("resolve worktree root %q: %w", worktreeRoot, err)
36		}
37		root = filepath.Clean(root)
38		if err := requireMetadataDirectory("worktree root", root); err != nil {
39			return WorktreeMetadata{}, err
40		}
41	
42		gitDirPath, err := resolveWorktreeGitDir(root)
43		if err != nil {
44			return WorktreeMetadata{}, err
45		}
46		commonDir, err := resolveWorktreeCommonDir(gitDirPath)
47		if err != nil {
48			return WorktreeMetadata{}, err
49		}
50		worktreeID, err := resolveWorktreeID(gitDirPath, commonDir)
51		if err != nil {
52			return WorktreeMetadata{}, err
53		}
54	
55		return WorktreeMetadata{
56			GitDir:     gitDirPath,
57			CommonDir:  commonDir,
58			WorktreeID: worktreeID,
59		}, nil
60	}
61	
62	func resolveWorktreeGitDir(worktreeRoot string) (string, error) {
63		gitEntry := filepath.Join(worktreeRoot, gitDir)
64		info, err := os.Lstat(gitEntry)
65		if errors.Is(err, fs.ErrNotExist) {
66			if rootErr := requireMetadataDirectory("worktree root", worktreeRoot); rootErr != nil {
67				return "", rootErr
68			}
69			return "", fmt.Errorf("%w at %s: %w", ErrWorktreeMetadataNotFound, gitEntry, err)
70		}
71		if err != nil {
72			return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
73		}
74		if info.Mode()&fs.ModeSymlink != 0 {
75			info, err = os.Stat(gitEntry)
76			if err != nil {
77				return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
78			}
79		}
80		if info.IsDir() {
81			return gitEntry, nil
82		}
83		if !info.Mode().IsRegular() {
84			return "", fmt.Errorf(".git entry at %s is neither a directory nor a regular file", gitEntry)
85		}
86	
87		content, err := os.ReadFile(gitEntry) //nolint:gosec // path is anchored at the explicit worktree root.
88		if err != nil {
89			return "", fmt.Errorf("read .git file at %s: %w", gitEntry, err)
90		}
91		pointer, ok := strings.CutPrefix(strings.TrimRight(string(content), "\r\n"), "gitdir: ")
92		if !ok {
93			return "", fmt.Errorf("parse .git file at %s: missing gitdir prefix", gitEntry)
94		}
95		if pointer == "" {
96			return "", fmt.Errorf("parse .git file at %s: empty gitdir value", gitEntry)
97		}
98	
99		resolved, err := resolveMetadataDirectory("Git directory", worktreeRoot, pointer)
100		if err != nil {
101			return "", err
102		}
103		return resolved, nil
104	}
105	
106	func resolveWorktreeCommonDir(gitDirPath string) (string, error) {
107		commonFile := filepath.Join(gitDirPath, "commondir")
108		info, err := os.Lstat(commonFile)
109		if errors.Is(err, fs.ErrNotExist) {
