103	func scanGitMetadataSources(repoRoot string, policy gitMetadataGuardPolicy) (gitMetadataGuardResult, error) {
104		packageValues, err := collectGuardPackageStringValues(repoRoot)
105		if err != nil {
106			return gitMetadataGuardResult{}, fmt.Errorf("collect package string values: %w", err)
107		}
108		fset := token.NewFileSet()
109		result := gitMetadataGuardResult{
110			legacyOwnersSeen:        map[string]bool{},
111			policyInspectionsSeen:   map[string]bool{},
112			metadataQueriesSeen:     map[guardMetadataQuery]bool{},
113			legacyResolverCallsSeen: map[string]bool{},
114		}
115	
116		err = filepath.WalkDir(repoRoot, func(path string, entry fs.DirEntry, walkErr error) error {
117			if walkErr != nil {
118				return walkErr
119			}
120			if entry.IsDir() {
121				return nil
122			}
123			rel, err := filepath.Rel(repoRoot, path)
124			if err != nil {
125				return err
126			}
127			rel = filepath.ToSlash(rel)
128			if !isGuardSourceFile(rel) {
129				return nil
130			}
131	
132			file, err := parser.ParseFile(fset, path, nil, 0)
133			if err != nil {
134				return err
135			}
136			values := packageValues[guardPackageKey(rel, file)]
137			valueResolver := newGuardValueResolver(fset, file, values)
138			gitrepoImports, dotImportedGitrepo := gitrepoImportNames(file)
139			samePackage := filepath.ToSlash(filepath.Dir(rel)) == "cmd/entire/cli/gitrepo"
140			for _, decl := range file.Decls {
141				fn, ok := decl.(*ast.FuncDecl)
142				if !ok || fn.Body == nil {
143					continue
144				}
145				key := guardSourceKey(rel, fn.Name.Name)
146				canonicalOwner := guardSourcePath(rel) == "gitrepo/metadata.go"
147				_, legacyOwner := policy.legacyTraversalOwners[key]
148				_, policyInspection := policy.policyDotGitInspections[key]
149	
150				for _, value := range []string{"gitdir: ", "gitdir:", "commondir"} {
151					if !valueResolver.contains(fn.Body, value) {
152						continue
153					}
154					if canonicalOwner {
155						result.canonicalTokens++
156						continue
157					}
158					if legacyOwner {
159						result.legacyOwnersSeen[key] = true
160						continue
161					}
162					result.violations = append(result.violations, fmt.Sprintf("%s independently parses Git metadata token %q; use gitrepo.ResolveWorktreeMetadata", fset.Position(fn.Pos()), value))
163				}
164				if valueResolver.contains(fn.Body, "rev-parse") {
165					for _, flag := range []string{"--absolute-git-dir", "--git-common-dir", "--git-dir", "--show-toplevel"} {
166						if !valueResolver.contains(fn.Body, flag) {
167							continue
168						}
169						query := guardMetadataQuery{source: key, flag: flag}
170						if _, allowed := policy.allowedMetadataQueries[query]; allowed {
171							result.metadataQueriesSeen[query] = true
172						} else {
173							result.violations = append(result.violations, fmt.Sprintf("%s runs an unaudited git rev-parse %s query; use gitrepo.ResolveWorktreeMetadata or document a semantic-query exception", fset.Position(fn.Pos()), flag))
174						}
175					}
176				}
177				ast.Inspect(fn.Body, func(node ast.Node) bool {
178					call, ok := node.(*ast.CallExpr)
179					if !ok {
180						return true
181					}
182					if isLegacyMetadataResolverCall(call, gitrepoImports, dotImportedGitrepo, samePackage) {
183						if _, allowed := policy.allowedLegacyCalls[key]; allowed {
184							result.legacyResolverCallsSeen[key] = true
185						} else {
186							result.violations = append(result.violations, fmt.Sprintf("%s calls a legacy Git metadata resolver; use gitrepo.ResolveWorktreeMetadata or document the migration exception", fset.Position(call.Pos())))
187						}
188					}
189					if !valueResolver.contains(call, ".git") || !isFilesystemMetadataInspection(call) || canonicalOwner {
190						return true
191					}
192					if legacyOwner {
193						result.legacyOwnersSeen[key] = true
194						return true
195					}
196					if policyInspection {
197						result.policyInspectionsSeen[key] = true
198						return true
199					}
200					result.violations = append(result.violations, fmt.Sprintf("%s independently inspects a .git entry; use gitrepo.ResolveWorktreeMetadata or document a narrow policy exception", fset.Position(call.Pos())))
201					return true
202				})
203			}
204			return nil
205		})
206		return result, err
207	}
