371	func isFilesystemMetadataInspection(call *ast.CallExpr) bool {
372		selector, ok := call.Fun.(*ast.SelectorExpr)
373		if !ok {
374			return false
375		}
376		switch selector.Sel.Name {
377		case "DirFS", "Lstat", "Open", "OpenFile", "OpenInRoot", "OpenRoot", "ReadDir", "ReadFile", "Readlink", "Stat":
