384	func collectGuardPackageStringValues(repoRoot string) (map[string]map[string]string, error) {
385		values := map[string]map[string]string{}
386		fset := token.NewFileSet()
387		err := filepath.WalkDir(repoRoot, func(path string, entry fs.DirEntry, walkErr error) error {
388			if walkErr != nil {
389				return walkErr
390			}
391			if entry.IsDir() {
392				return nil
393			}
394			rel, err := filepath.Rel(repoRoot, path)
395			if err != nil {
396				return err
397			}
398			rel = filepath.ToSlash(rel)
399			if !isGuardSourceFile(rel) {
400				return nil
401			}
402			file, err := parser.ParseFile(fset, path, nil, 0)
403			if err != nil {
404				return err
405			}
406			key := guardPackageKey(rel, file)
407			if values[key] == nil {
408				values[key] = map[string]string{}
409			}
410			for name, value := range packageStringValues(file) {
411				values[key][name] = value
412			}
413			return nil
414		})
415		return values, err
416	}
