418	func packageStringValues(file *ast.File) map[string]string {
419		values := map[string]string{}
420		for _, decl := range file.Decls {
421			gen, ok := decl.(*ast.GenDecl)
422			if !ok {
423				continue
424			}
425			for _, spec := range gen.Specs {
426				valueSpec, ok := spec.(*ast.ValueSpec)
427				if !ok {
428					continue
429				}
430				for i, expr := range valueSpec.Values {
431					literal, ok := expr.(*ast.BasicLit)
432					if !ok || literal.Kind != token.STRING || i >= len(valueSpec.Names) {
433						continue
434					}
435					unquoted, err := strconv.Unquote(literal.Value)
436					if err == nil {
437						values[valueSpec.Names[i].Name] = unquoted
438					}
439				}
440			}
441		}
442		return values
443	}
