445	func gitrepoImportNames(file *ast.File) (map[string]bool, bool) {
446		names := map[string]bool{}
447		dotImported := false
448		for _, spec := range file.Imports {
449			path, err := strconv.Unquote(spec.Path.Value)
450			if err != nil || path != "github.com/entireio/cli/cmd/entire/cli/gitrepo" {
451				continue
452			}
453			switch {
454			case spec.Name == nil:
455				names["gitrepo"] = true
456			case spec.Name.Name == ".":
457				dotImported = true
458			case spec.Name.Name != "_":
459				names[spec.Name.Name] = true
460			}
461		}
462		return names, dotImported
463	}
