465	func isLegacyMetadataResolverCall(call *ast.CallExpr, importNames map[string]bool, dotImported, samePackage bool) bool {
466		legacyName := func(name string) bool {
467			return name == "ResolveDotGitPath" || name == "ResolveCommonGitPath"
468		}
469		if ident, ok := call.Fun.(*ast.Ident); ok {
470			return (dotImported || samePackage) && legacyName(ident.Name)
471		}
472		selector, ok := call.Fun.(*ast.SelectorExpr)
473		if !ok || !legacyName(selector.Sel.Name) {
474			return false
475		}
476		pkg, ok := selector.X.(*ast.Ident)
477		return ok && importNames[pkg.Name]
478	}
