498	type guardValueResolver struct {
499		packageValues map[string]string
500		typeInfo      *types.Info
501		bindings      map[types.Object]ast.Expr
502	}
503	
504	func newGuardValueResolver(fset *token.FileSet, file *ast.File, packageValues map[string]string) guardValueResolver {
505		typeInfo := &types.Info{
506			Defs: map[*ast.Ident]types.Object{},
507			Uses: map[*ast.Ident]types.Object{},
508		}
509		config := types.Config{Error: func(error) {}}
510		_, typeErr := config.Check(file.Name.Name, fset, []*ast.File{file}, typeInfo)
511		// Files are checked in isolation, so unresolved cross-file imports are
512		// expected; local definitions collected before that error remain usable.
513		if typeErr != nil && len(typeInfo.Defs) == 0 && len(typeInfo.Uses) == 0 {
514			return guardValueResolver{packageValues: packageValues, typeInfo: typeInfo}
515		}
516		return guardValueResolver{
517			packageValues: packageValues,
518			typeInfo:      typeInfo,
519			bindings:      guardValueBindings(file, typeInfo),
520		}
521	}
522	
523	func guardValueBindings(file *ast.File, typeInfo *types.Info) map[types.Object]ast.Expr {
524		bindings := map[types.Object]ast.Expr{}
525		ast.Inspect(file, func(node ast.Node) bool {
526			switch decl := node.(type) {
527			case *ast.ValueSpec:
528				for i, name := range decl.Names {
529					if object := typeInfo.Defs[name]; object != nil {
530						bindings[object] = expressionAt(decl.Values, i)
531					}
532				}
533			case *ast.AssignStmt:
534				if decl.Tok != token.DEFINE {
535					return true
536				}
537				for i, lhs := range decl.Lhs {
538					name, ok := lhs.(*ast.Ident)
539					if !ok {
540						continue
541					}
542					if object := typeInfo.Defs[name]; object != nil {
543						bindings[object] = expressionAt(decl.Rhs, i)
544					}
545				}
546			}
547			return true
548		})
549		return bindings
550	}
551	
552	func expressionAt(expressions []ast.Expr, index int) ast.Expr {
553		if index < len(expressions) {
554			return expressions[index]
555		}
556		if len(expressions) == 1 {
557			return expressions[0]
558		}
559		return nil
560	}
561	
562	func (r guardValueResolver) contains(node ast.Node, want string) bool {
563		return r.containsSeen(node, want, map[types.Object]bool{})
564	}
565	
566	func (r guardValueResolver) containsSeen(node ast.Node, want string, seen map[types.Object]bool) bool {
567		found := false
568		ast.Inspect(node, func(n ast.Node) bool {
569			switch value := n.(type) {
570			case *ast.BasicLit:
571				if value.Kind != token.STRING {
572					return true
573				}
574				unquoted, err := strconv.Unquote(value.Value)
575				if err == nil && unquoted == want {
576					found = true
577					return false
578				}
579			case *ast.Ident:
580				object := r.typeInfo.Uses[value]
581				if object == nil {
582					object = r.typeInfo.Defs[value]
583				}
584				if object == nil {
585					if r.packageValues[value.Name] == want {
586						found = true
587					}
588					return false
589				}
590				if seen[object] {
591					return false
592				}
593				expr := r.bindings[object]
594				if expr == nil {
595					return false
596				}
597				seen[object] = true
598				if r.containsSeen(expr, want, seen) {
599					found = true
600				}
601				delete(seen, object)
602				return false
603			}
604			return !found
605		})
606		return found
607	}
608	
609	func guardPackageKey(rel string, file *ast.File) string {
610		return filepath.ToSlash(filepath.Dir(rel)) + ":" + file.Name.Name
611	}
612	
613	func guardSourceKey(rel, function string) string {
614		return guardSourcePath(rel) + ":" + function
615	}
616	
617	func guardSourcePath(rel string) string {
618		return strings.TrimPrefix(filepath.ToSlash(rel), "cmd/entire/cli/")
619	}
620	
621	func isGuardSourceFile(rel string) bool {
622		rel = filepath.ToSlash(rel)
623		if !strings.HasSuffix(rel, ".go") || strings.HasSuffix(rel, "_test.go") {
624			return false
625		}
626		for _, prefix := range []string{
627			"cmd/entire/cli/agent/testutil/",
628			"cmd/entire/cli/benchutil/",
629			"cmd/entire/cli/integration_test/",
630			"e2e/",
631		} {
632			if strings.HasPrefix(rel, prefix) {
633				return false
634			}
635		}
636		return true
637	}
