package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
)

func run(dir string, args ...string) {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	if out, err := cmd.CombinedOutput(); err != nil {
		panic(fmt.Sprintf("git %v: %v\n%s", args, err, out))
	}
}

func timeResolve(root string, n int) time.Duration {
	start := time.Now()
	for i := 0; i < n; i++ {
		if _, err := gitrepo.ResolveWorktreeMetadata(root); err != nil {
			panic(err)
		}
	}
	return time.Since(start) / time.Duration(n)
}

func timeSubprocess(root string, n int) time.Duration {
	start := time.Now()
	for i := 0; i < n; i++ {
		cmd := exec.Command("git", "-C", root, "rev-parse", "--git-common-dir")
		if _, err := cmd.Output(); err != nil {
			panic(err)
		}
	}
	return time.Since(start) / time.Duration(n)
}

func main() {
	tmp, err := os.MkdirTemp("", "benchresolve")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(tmp)

	mainRoot := filepath.Join(tmp, "main")
	if err := os.MkdirAll(mainRoot, 0o755); err != nil {
		panic(err)
	}
	run(mainRoot, "init", "-q")
	run(mainRoot, "config", "user.email", "b@b")
	run(mainRoot, "config", "user.name", "b")
	if err := os.WriteFile(filepath.Join(mainRoot, "f.txt"), []byte("x"), 0o644); err != nil {
		panic(err)
	}
	run(mainRoot, "add", "f.txt")
	run(mainRoot, "commit", "-q", "-m", "init", "--no-gpg-sign")
	linkedRoot := filepath.Join(tmp, "linked")
	run(mainRoot, "worktree", "add", "-q", "-b", "linked", linkedRoot)

	const n = 2000
	fmt.Printf("new resolver, main worktree:   %v/op\n", timeResolve(mainRoot, n))
	fmt.Printf("new resolver, linked worktree: %v/op\n", timeResolve(linkedRoot, n))
	fmt.Printf("old subprocess, main worktree: %v/op (n=50)\n", timeSubprocess(mainRoot, 50))
}

